using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Removes a reaction from a message. A chosen reaction can always be removed
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> RemoveMessageReactionAsync(long chatId = default, long messageId = default, ReactionType reactionType = default)
    {

           using var activity =  StartCallActivity("RemoveMessageReactionAsync", typeof(RemoveMessageReaction).FullName ?? "RemoveMessageReactionAsync");

           try
           {
             return client.RemoveMessageReactionAsync(chatId, messageId, reactionType);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
